ALTER TABLE "ops"."deletion_request" ADD CONSTRAINT "ck_deletion_links" CHECK (("ops"."deletion_request"."state" IN ('completed','cancelled') AND "ops"."deletion_request"."user_id" IS NULL AND "ops"."deletion_request"."workspace_id" IS NULL) OR ("ops"."deletion_request"."state"<>'completed' AND "ops"."deletion_request"."user_id"="ops"."deletion_request"."target_user_id" AND "ops"."deletion_request"."workspace_id"="ops"."deletion_request"."target_workspace_id" AND "ops"."deletion_request"."user_id" IS NOT NULL AND "ops"."deletion_request"."workspace_id" IS NOT NULL));